function esc(v){return String(v==null?'':v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}function n(v){v=Number(v);return Number.isFinite(v)?v:0}function fmt(v,d=0){return n(v).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d})}function money(v,c='EGP'){return fmt(v,2)+' '+esc(c||'EGP')}function date10(v){return String(v||'').slice(0,10)}function today(){const d=new Date(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return d.getFullYear()+'-'+m+'-'+day}function addDays(s,d){const x=new Date(s+'T12:00:00');x.setDate(x.getDate()+d);return x.toISOString().slice(0,10)}function daysInclusive(from,to){if(!from||!to||to<from)return 0;return Math.floor((new Date(to+'T12:00:00')-new Date(from+'T12:00:00'))/86400000)+1}function perm(k){const u=(SESSION&&SESSION.user)||{},sp=(DATA&&DATA.permissions)||{};return !!(u.is_admin||(u.mountain&&u.mountain.permissions&&(u.mountain.permissions.all||u.mountain.permissions[k]))||sp.all||sp[k])}function showLoader(text){$('loaderText').textContent=text||L('جارٍ التحميل...','Loading...');$('loader').classList.add('show')}function hideLoader(){$('loader').classList.remove('show')}function toast(msg,bad){const el=$('toast');const base=String(msg||'');el.textContent=bad?L('تعذر الإرسال إلى Google Sheets: ','Could not send to Google Sheets: ')+base:(/Google Sheets|جوجل شيت/i.test(base)?base:L('تم قبول البيانات وحفظها في Google Sheets — ','Data accepted and saved to Google Sheets — ')+base);el.className='toast show '+(bad?'bad':'good');clearTimeout(window.__mountainToastTimer);window.__mountainToastTimer=setTimeout(()=>el.classList.remove('show'),5200)}
function api(action,params={}){return new Promise((resolve,reject)=>{if(!API_URL)return reject(new Error('رابط API غير موجود'));const cb='ait_mtn_'+Date.now()+'_'+Math.random().toString(36).slice(2);const s=document.createElement('script');let done=false;const finish=()=>{done=true;delete window[cb];s.remove()};window[cb]=r=>{finish();if(!r||r.ok===false)reject(new Error(r&&r.message||'فشل الطلب'));else resolve(r)};s.onerror=()=>{if(!done){finish();reject(new Error('تعذر الاتصال بالخادم'))}};setTimeout(()=>{if(!done){finish();reject(new Error('انتهت مهلة الاتصال'))}},45000);const q=new URLSearchParams({module:'mountain_entry',action,token:TOKEN,callback:cb,t:Date.now(),...params});s.src=API_URL+'?'+q.toString();document.body.appendChild(s)})}
function utf8Base64(value){const bytes=new TextEncoder().encode(String(value||''));let binary='';const size=8192;for(let i=0;i<bytes.length;i+=size)binary+=String.fromCharCode(...bytes.subarray(i,i+size));return btoa(binary)}
async function payloadApi(action,obj,extra={}){const raw=JSON.stringify(obj||{}),requestId='MTN-'+Date.now()+'-'+Math.random().toString(36).slice(2),encodedLength=encodeURIComponent(raw).length;if(encodedLength<=1800)return api(action,{...extra,payload:raw,client_request_id:requestId});const encoded=utf8Base64(raw),chunkSize=1400,total=Math.ceil(encoded.length/chunkSize),uploadId='PAY-'+Date.now()+'-'+Math.random().toString(36).slice(2);for(let i=0;i<total;i++){await api('stagepayload',{upload_id:uploadId,chunk_index:i,total_chunks:total,encoding:'base64',chunk:encoded.slice(i*chunkSize,(i+1)*chunkSize),client_request_id:requestId})}return api(action,{...extra,payload_ref:uploadId,client_request_id:requestId})}
