function renderDetails(){const rows=DATA.rows||[];$('tableCount').textContent=DATA.count+' سجل';$('detailBody').innerHTML=rows.length?rows.map(r=>'<tr><td>'+esc(r.date)+'</td><td><b>'+esc(r.employee_name)+'</b></td><td>'+esc(r.mine_name||r.mine_id)+'</td><td>'+esc(r.department)+'</td><td>'+esc(r.job_title)+'</td><td>'+badge(r.status)+'</td><td>'+esc(r.check_in_time||'—')+'</td><td>'+esc(r.mountain_entry_time||'—')+'</td><td>'+esc(r.mountain_exit_time||'—')+'</td><td>'+esc(r.check_out_time||'—')+'</td><td>'+fmt(r.worked_hours,1)+'</td><td>'+fmt(r.late_minutes)+'</td><td>'+esc(r.vehicle_name||'—')+'</td><td>'+esc(r.pickup_point||'—')+'</td><td>'+money(r.estimated_expense,r.currency)+'</td><td>'+esc(r.notes||'')+'</td></tr>').join(''):emptyRow(16,'لا توجد سجلات مطابقة');const p=DATA.pagination||{page:1,pages:1};$('pageInfo').textContent=p.page+' / '+p.pages;$('prevPage').disabled=p.page<=1;$('nextPage').disabled=p.page>=p.pages}
function daysBetween(from,to){const out=[];for(let d=from;d<=to&&out.length<62;d=addDays(d,1))out.push(d);return out}
function leaveDayKind(leave,date){const type=String(leave.leave_type||'').toLowerCase();if(type!=='rotation_leave')return type==='sick_leave'?'sick':'annual';const start=date10(leave.start_date),index=daysInclusive(start,date),allowed=Math.max(0,n(leave.rotation_leave_days_allowed||leave.approved_leave_days));if(index<=allowed)return'rotation';const excess=String(leave.excess_treatment||'annual').toLowerCase();return excess==='sick_leave'?'sick':excess==='absent'?'absent':'annual'}
function renderLeaves(){const leaves=DATA.leaves||[],missions=DATA.missions||[],days=daysBetween(DATA.range.from,DATA.range.to),emps=[...new Map((DATA.filters.employees||[]).map(e=>[e.id,e])).values()];$('leaveCount').textContent=(leaves.length+missions.length)+' '+L('سجل','record(s)');const leaveRows=leaves.map(r=>'<tr><td>'+esc(r.employee_name)+'</td><td>'+esc(r.department)+'</td><td><b>'+esc(leaveLabel(r.leave_type))+'</b></td><td>'+esc(r.work_period_from||'—')+' → '+esc(r.work_period_to||'—')+'</td><td>'+fmt(r.site_days_completed)+'</td><td>'+esc(r.start_date)+'</td><td>'+esc(r.end_date)+'</td><td>'+fmt(r.requested_days||daysInclusive(date10(r.start_date),date10(r.end_date)))+'</td><td>'+fmt(r.rotation_leave_days_allowed||0)+'</td><td>'+fmt(r.excess_days||0)+(n(r.excess_days)>0?' · '+esc(excessLabel(r.excess_treatment)):'')+'</td><td>'+esc(r.return_date)+'</td><td>'+esc(r.status)+'</td><td>'+esc(r.reason||r.notes||'')+'</td></tr>');const missionRows=missions.map(r=>'<tr><td>'+esc(r.employee_name)+'</td><td>'+esc(r.department)+'</td><td><b>'+L('مأمورية','Mission')+'</b></td><td>—</td><td>—</td><td>'+esc(r.start_date)+'</td><td>'+esc(r.end_date)+'</td><td>'+fmt(daysInclusive(date10(r.start_date),date10(r.end_date)))+'</td><td>—</td><td>—</td><td>—</td><td>'+esc(r.status)+'</td><td>'+esc(r.destination||r.notes||'')+'</td></tr>');$('leaveBody').innerHTML=(leaveRows.length+missionRows.length)?leaveRows.concat(missionRows).join(''):emptyRow(13,L('لا توجد إجازات أو مأموريات','No leaves or missions'));const byEmp={};leaves.filter(l=>['approved','confirmed','active'].includes(String(l.status||'approved').toLowerCase())).forEach(l=>(byEmp[l.employee_id]=byEmp[l.employee_id]||[]).push(l));let h='<table><thead><tr><th>'+L('الموظف','Employee')+'</th>'+days.map(d=>'<th class="leave-day">'+esc(d.slice(8))+'</th>').join('')+'</tr></thead><tbody>';emps.forEach(e=>{h+='<tr><td><b>'+esc(e.name)+'</b></td>';days.forEach(d=>{const ls=byEmp[e.id]||[],leave=ls.find(l=>d>=date10(l.start_date)&&d<=date10(l.end_date)),ret=ls.some(l=>d===date10(l.return_date));let cell='';if(leave)cell='<i class="leave-fill '+leaveDayKind(leave,d)+'" title="'+esc(leaveLabel(leave.leave_type))+'"></i>';else if(ret)cell='<i class="leave-return" title="'+L('تاريخ العودة','Return date')+'"></i>';h+='<td class="leave-cell">'+cell+'</td>'});h+='</tr>'});h+='</tbody></table>';$('leaveCalendar').innerHTML=emps.length?h:'<div class="empty">'+L('لا توجد بيانات موظفين','No employee data')+'</div>'}
function renderVehicles(){if($('addCompanyVehicleBtn'))$('addCompanyVehicleBtn').classList.toggle('hidden',!perm('manage_vehicles'));const rows=DATA.vehicles||[];$('vehicleMasterCards').innerHTML=rows.length?rows.map(v=>{const points=splitLookup(v.route_points||v.nearest_pickup_point_ids||v.nearest_residence_ids).join('، ')||'—',passengers=splitLookup(v.allowed_passenger_names).join('، ')||'—',fault=String(v.vehicle_status||'').toLowerCase()==='maintenance';return '<div class="vehicle-card company-vehicle-card"><div class="vehicle-card-title"><div><b>'+esc(v.vehicle_name||v.plate_number)+'</b><small>'+esc((v.vehicle_brand||v.vehicle_type||'—')+(v.vehicle_model?' · '+v.vehicle_model:''))+'</small></div><span class="vehicle-status">'+esc(fault?'بها عطل':(v.vehicle_status||'available'))+'</span></div><div class="meta"><span>'+L('رقم السيارة: ','Plate: ')+esc(v.plate_number||'—')+'</span><span>'+L('السعة: ','Capacity: ')+fmt(v.capacity_passengers||4)+' بدون السائق</span></div><p>'+L('الأشخاص المسموح لهم: ','Allowed passengers: ')+esc(passengers)+'</p><div class="meta stacked"><span>'+L('نقاط السير: ','Route points: ')+esc(points)+'</span>'+(fault?'<span>'+L('العطل: ','Fault: ')+esc(v.fault_description||'—')+' — '+esc(v.fault_reason||'—')+'</span>':'')+'</div>'+(perm('manage_vehicles')?'<button class="btn ghost vehicle-edit-btn" data-edit-vehicle="'+esc(v.vehicle_id)+'">'+L('تعديل السيارة','Edit vehicle')+'</button>':'')+'</div>'}).join(''):'<div class="empty">'+L('لا توجد عربيات','No vehicles')+'</div>';document.querySelectorAll('[data-edit-vehicle]').forEach(b=>b.onclick=()=>openCompanyVehicleForm(b.dataset.editVehicle));const req=DATA.vehicle_requests||[];$('requestCount').textContent=req.length+' طلب';$('requestBody').innerHTML=req.length?req.map(r=>'<tr><td>'+esc(r.request_date)+'</td><td>'+esc(r.mine_id||'—')+'</td><td>'+esc(r.request_type==='add_vehicle'?'زيادة عربية':'إلغاء عربية')+'</td><td>'+esc(r.vehicle_id||'—')+'</td><td>'+esc(r.expected_departure_time||'—')+'</td><td>'+esc(r.reason)+'</td><td>'+esc(r.status)+'</td><td>'+esc(r.requested_by)+'</td></tr>').join(''):emptyRow(8,'لا توجد طلبات')}
function renderExpenses(){const rows=DATA.expenses||[];$('expenseCount').textContent=rows.length+' سجل معتمد/مولد';$('expenseBody').innerHTML=rows.length?rows.map(r=>'<tr><td>'+esc(r.expense_date)+'</td><td><b>'+esc(r.employee_name)+'</b></td><td>'+esc(r.department)+'</td><td>'+badge(r.final_status)+'</td><td>'+fmt(r.base_amount,2)+'</td><td>'+fmt(r.transport_amount,2)+'</td><td>'+fmt(r.manual_adjustment,2)+'</td><td><b>'+fmt(r.total_amount,2)+'</b></td><td>'+esc(r.currency)+'</td><td>'+esc(r.approval_status)+'</td><td>'+esc(r.adjustment_reason||'')+'</td><td>'+(perm('manage_expenses')&&String(r.approval_status).toLowerCase()!=='approved'?'<button class="btn ghost" data-adjust="'+esc(r.expense_id)+'">تعديل</button>':'—')+'</td></tr>').join(''):emptyRow(12,'لم يتم توليد مصروفات للفترة');document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>openExpenseAdjustment(b.dataset.adjust));renderExpensePeriods()}
