function renderPermissions(){if(!perm('view_expenses')){$('expensesTab').classList.add('hidden');$('tab-expenses').classList.add('hidden');if(ACTIVE_TAB==='expenses')switchTab('today')}else{$('expensesTab').classList.remove('hidden');$('tab-expenses').classList.remove('hidden')}const canInput=['record_team','manage_employees','manage_leaves','manage_vehicles'].some(perm);const input=$('inputBtn');input.style.display='inline-flex';input.dataset.canInput=canInput?'1':'0';input.setAttribute('aria-disabled',canInput?'false':'true');input.title=canInput?'':L('لا توجد صلاحيات إدخال مفعلة لهذا الحساب','No input permissions are enabled for this account');$('excelBtn').style.display=((SESSION&&SESSION.user&&SESSION.user.can_export)||perm('export'))?'inline-flex':'none'}
