function employeeOptions(){return(DATA.filters.employees||[]).map(e=>'<option value="'+esc(e.id)+'">'+esc(e.name)+' — '+esc(e.department)+'</option>').join('')}function vehicleOptions(){return(DATA.filters.vehicles||[]).map(v=>'<option value="'+esc(v.id)+'">'+esc(v.name)+'</option>').join('')}function formField(label,id,type='text',value='',extra=''){return'<div class="field"><label>'+label+'</label><input class="input" id="'+id+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></div>'}function selectField(label,id,options){return'<div class="field"><label>'+label+'</label><select class="select" id="'+id+'">'+options+'</select></div>'}
