function employeePassengerChoices(selectedIds=[]){const selected=new Set((selectedIds||[]).map(String)),emps=((DATA&&DATA.filters&&DATA.filters.employees)||[]);return '<div class="vehicle-choice-grid">'+(emps.length?emps.map(e=>'<label class="vehicle-choice"><input type="checkbox" data-vehicle-passenger value="'+esc(e.id)+'" '+(selected.has(String(e.id))?'checked':'')+'><span><b>'+esc(e.name)+'</b><small>'+esc((e.department||'—')+' · '+(e.job_title||'—'))+'</small></span></label>').join(''):'<div class="empty">لا توجد بيانات موظفين لاختيار الركاب</div>')+'</div>'}
function lookupKey(kind){return kind==='mine'?'employee_mine_options':kind==='job'?'employee_job_options':kind==='residence'?'employee_residence_options':'vehicle_route_point_options'}
function splitLookup(value){return String(value||'').split(/[|,،;\n]+/).map(x=>x.trim()).filter(Boolean)}
function uniqueText(values){const seen=new Set(),out=[];(values||[]).forEach(v=>{const clean=String(v||'').trim(),key=clean.toLowerCase();if(clean&&!seen.has(key)){seen.add(key);out.push(clean)}});return out}
function lookupOptions(kind){const settings=(DATA&&DATA.settings)||{},key=lookupKey(kind),stored=splitLookup(settings[key]||localStorage.getItem('ait_mtn_'+key)||''),f=(DATA&&DATA.filters)||{};let dynamic=[],defaults=[];if(kind==='mine'){dynamic=f.mines||[];defaults=DEFAULT_MINE_OPTIONS}else if(kind==='job'){dynamic=f.jobs||[];defaults=DEFAULT_JOB_OPTIONS}else if(kind==='residence'){defaults=DEFAULT_RESIDENCE_OPTIONS}else{defaults=DEFAULT_RESIDENCE_OPTIONS;dynamic=((DATA&&DATA.vehicles)||[]).flatMap(v=>splitLookup(v.route_points||v.nearest_pickup_point_ids||v.nearest_residence_ids))}return uniqueText([].concat(stored,defaults,dynamic))}
function optionHtml(values,selected=[],placeholder=''){const chosen=new Set((Array.isArray(selected)?selected:[selected]).map(String));return (placeholder?'<option value="">'+esc(placeholder)+'</option>':'')+(values||[]).map(v=>'<option value="'+esc(v)+'" '+(chosen.has(String(v))?'selected':'')+'>'+esc(v)+'</option>').join('')}
function lookupSelectField(label,id,kind,selected=[],multiple=false){const options=lookupOptions(kind),multi=multiple?' multiple size="5"':'',req=label.indexOf('*')>=0?' required':'';return '<div class="field lookup-field"><label>'+label+'</label><select class="select" id="'+id+'" data-lookup-kind="'+kind+'"'+multi+req+'>'+optionHtml(options,selected,multiple?'':'اختر')+'</select><div class="lookup-actions"><button type="button" class="btn ghost" data-lookup-add="'+kind+'" data-lookup-target="'+id+'">إضافة</button><button type="button" class="btn ghost" data-lookup-edit="'+kind+'" data-lookup-target="'+id+'">تعديل</button><button type="button" class="btn ghost danger" data-lookup-delete="'+kind+'" data-lookup-target="'+id+'">حذف</button></div></div>'}
function selectedValues(id){const el=$(id);if(!el)return[];return el.multiple?[...el.selectedOptions].map(o=>o.value).filter(Boolean):[el.value].filter(Boolean)}
function refreshLookupSelect(id,kind,selected){const el=$(id);if(!el)return;const multi=el.multiple;el.innerHTML=optionHtml(lookupOptions(kind),selected===undefined?selectedValues(id):selected,multi?'':'اختر')}
async function saveLookupOptions(kind,options){const key=lookupKey(kind),clean=uniqueText(options);if(!clean.length){toast('لا يمكن ترك القائمة فارغة.',true);return false}if(DATA){DATA.settings=DATA.settings||{};DATA.settings[key]=clean.join('|')}localStorage.setItem('ait_mtn_'+key,clean.join('|'));try{await payloadApi('savelookupoptions',{kind:kind,options:clean});toast('تم تحديث القائمة')}catch(e){toast('تم تحديث القائمة على هذا الجهاز فقط: '+e.message,true)}return true}
async function addLookupOption(kind,target){const value=prompt('اكتب القيمة الجديدة');if(!value||!value.trim())return;const options=lookupOptions(kind);options.push(value.trim());if(await saveLookupOptions(kind,options))refreshLookupSelect(target,kind,[value.trim()])}
async function editLookupOption(kind,target){const current=selectedValues(target)[0];if(!current)return toast('اختر قيمة لتعديلها أولًا.',true);const value=prompt('عدّل القيمة',current);if(!value||!value.trim())return;const options=lookupOptions(kind).map(x=>x===current?value.trim():x);if(await saveLookupOptions(kind,options))refreshLookupSelect(target,kind,[value.trim()])}
async function deleteLookupOption(kind,target){const selected=selectedValues(target);if(!selected.length)return toast('اختر قيمة لحذفها أولًا.',true);if(!confirm('حذف: '+selected.join('، ')+'؟'))return;const del=new Set(selected),options=lookupOptions(kind).filter(x=>!del.has(x));if(await saveLookupOptions(kind,options))refreshLookupSelect(target,kind,[])}
function bindLookupButtons(){document.querySelectorAll('[data-lookup-add]').forEach(b=>b.onclick=()=>addLookupOption(b.dataset.lookupAdd,b.dataset.lookupTarget));document.querySelectorAll('[data-lookup-edit]').forEach(b=>b.onclick=()=>editLookupOption(b.dataset.lookupEdit,b.dataset.lookupTarget));document.querySelectorAll('[data-lookup-delete]').forEach(b=>b.onclick=()=>deleteLookupOption(b.dataset.lookupDelete,b.dataset.lookupTarget))}
function managerOptions(){const emps=((DATA&&DATA.filters&&DATA.filters.employees)||[]),managers=emps.filter(e=>/مدير|manager/i.test(String(e.job_title||''))),list=managers.length?managers:emps;return '<option value="">اختر المدير المباشر</option>'+list.map(e=>'<option value="'+esc(e.id)+'">'+esc(e.name)+' — '+esc(e.job_title||e.department||'')+'</option>').join('')}
